// Un e-mail récapitulatif par Responsable : regroupe les résultats en attente par adresse.
const lignes = $('Resultats en attente').first().json.resultats || [];
const parResponsable = {};
for (const r of lignes) {
  const cle = r.responsableEmail;
  if (!parResponsable[cle]) parResponsable[cle] = { email: cle, nom: r.responsableNom, lien: r.lienValidation, resultats: [] };
  parResponsable[cle].resultats.push(r);
}
const ligneHtml = (r) => '<tr>'
  + '<td style="padding:8px;border-bottom:1px solid #E3E9E7">' + (r.critique ? '<b style="color:#B3261E">Critique</b> ' : '') + r.analyse + '</td>'
  + '<td style="padding:8px;border-bottom:1px solid #E3E9E7">' + r.demandeReference + '</td>'
  + '<td style="padding:8px;border-bottom:1px solid #E3E9E7">' + (r.nomLaboratoire || '') + '</td>'
  + '<td style="padding:8px;border-bottom:1px solid #E3E9E7;text-align:right">' + r.heuresAttente + ' h</td></tr>';
return Object.values(parResponsable).map(g => {
  const n = g.resultats.length;
  const critiques = g.resultats.filter(r => r.critique).length;
  const html = '<div style="margin:0;padding:24px 12px;background:#F4F7F6;font-family:Arial,Helvetica,sans-serif;color:#1A2A2E">'
    + '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;margin:0 auto;background:#FFFFFF;border-radius:16px;overflow:hidden">'
    + '<tr><td style="padding:22px 28px;background:#1A4A54"><p style="margin:0;color:#C8E86A;font-size:13px;font-weight:bold;letter-spacing:1px">LABFLOW LIMS</p>'
    + '<h1 style="margin:8px 0 0;color:#FFFFFF;font-size:22px;line-height:1.3">Résultats en attente de validation</h1></td></tr>'
    + '<tr><td style="padding:28px;font-size:15px;line-height:1.6">'
    + '<p style="margin:0 0 12px">Bonjour ' + (g.nom || '') + ',</p>'
    + '<p style="margin:0 0 12px">' + n + ' résultat(s) validé(s) par les techniciens attendent votre décision'
    + (critiques ? ', dont <b style="color:#B3261E">' + critiques + ' critique(s)</b>' : '') + '.</p>'
    + '<table width="100%" cellspacing="0" cellpadding="0" style="font-size:14px;border-collapse:collapse">'
    + '<tr style="background:#F4F7F6"><th align="left" style="padding:8px">Analyse</th><th align="left" style="padding:8px">Demande</th>'
    + '<th align="left" style="padding:8px">Laboratoire</th><th align="right" style="padding:8px">Attente</th></tr>'
    + g.resultats.map(ligneHtml).join('') + '</table>'
    + '<a href="' + g.lien + '" style="display:inline-block;margin:20px 0 8px;padding:12px 22px;border-radius:999px;background:#1A4A54;color:#FFFFFF;font-size:14px;font-weight:bold;text-decoration:none">Valider les résultats</a>'
    + '<p style="margin:24px 0 0;color:#5B6B70;font-size:13px">L’équipe LabFlow</p></td></tr>'
    + '<tr><td style="padding:16px 28px 24px;color:#7A8A8E;font-size:12px">Cet e-mail a été envoyé automatiquement. Merci de ne pas y répondre.</td></tr></table></div>';
  return { json: { to: g.email, subject: n + ' résultat(s) en attente de votre validation' + (critiques ? ' (' + critiques + ' critique(s))' : ''), html } };
});
